SourceCode.Declaration:
/// <summary>
/// One group of the accuracy report. Tolerance: the tolerance that applies to this group, for display
/// (per ABC class when grouped by class).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountAccuracyRow
{
    str  groupKey;
    str  label;
    int  countedLines;
    int  accurateLines;
    real accuracyPct;
    real varianceValue;
    str  tolerance;

}

Method.Source:
[DataMemberAttribute('GroupKey')]
public str parmGroupKey(str _value = groupKey)
{
    groupKey = _value;
    return groupKey;
}

[DataMemberAttribute('Label')]
public str parmLabel(str _value = label)
{
    label = _value;
    return label;
}

[DataMemberAttribute('CountedLines')]
public int parmCountedLines(int _value = countedLines)
{
    countedLines = _value;
    return countedLines;
}

[DataMemberAttribute('AccurateLines')]
public int parmAccurateLines(int _value = accurateLines)
{
    accurateLines = _value;
    return accurateLines;
}

[DataMemberAttribute('AccuracyPct')]
public real parmAccuracyPct(real _value = accuracyPct)
{
    accuracyPct = _value;
    return accuracyPct;
}

[DataMemberAttribute('VarianceValue')]
public real parmVarianceValue(real _value = varianceValue)
{
    varianceValue = _value;
    return varianceValue;
}

[DataMemberAttribute('Tolerance')]
public str parmTolerance(str _value = tolerance)
{
    tolerance = _value;
    return tolerance;
}
